INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/100, /*where_type*/24, /*character_id*/129901, /*face_type*/1, /*character_name*/'惠理子', /*description*/'祝贺你训练成功。\n该表扬的时候就要好好表扬，\n这也是教官的职责。还是说，\n你更喜欢被骂呢？　嘻嘻。', /*voice_id*/100, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/10.85, /*change_face_type*/7, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/101, /*where_type*/24, /*character_id*/129901, /*face_type*/1, /*character_name*/'惠理子', /*description*/'虽然训练很严酷，但结束后再回头看看，\n就会觉得时间很短暂呢。\n说实话，我都有点没破坏够……\n不，没什么哦。嘻嘻。', /*voice_id*/101, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/11.15, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/102, /*where_type*/24, /*character_id*/129901, /*face_type*/7, /*character_name*/'惠理子', /*description*/'将挡住去路的那些讨厌的碍事者们\n统统击溃，华丽地冲向终点！\n仿佛是在象征着我和\n那位大人的人生旅程……', /*voice_id*/102, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/6.4, /*change_face_type*/5, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/103, /*where_type*/24, /*character_id*/129901, /*face_type*/3, /*character_name*/'惠理子', /*description*/'真是没出息的结果。\n不过，还有挽回的机会。\n为了摆脱垃圾臭虫的地位，\n下次给我拼尽全力。听懂了吗？', /*voice_id*/103, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/3, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/104, /*where_type*/24, /*character_id*/129901, /*face_type*/2, /*character_name*/'惠理子', /*description*/'嘻嘻……啊，请别担心，\n我只是在考虑，拿到如此\n窝囊废成绩的家伙，该施以\n怎样的惩罚才好呢……嘻嘻嘻。', /*voice_id*/104, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/2.43, /*change_face_type*/8, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/105, /*where_type*/24, /*character_id*/129901, /*face_type*/4, /*character_name*/'惠理子', /*description*/'如果我无法被认可为一名合格的教官，\n会让那位大人失望的……\n唯独这件事绝不允许发生。\n你们也明白这一点吧？', /*voice_id*/105, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/9.08, /*change_face_type*/3, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/106, /*where_type*/24, /*character_id*/129901, /*face_type*/6, /*character_name*/'惠理子', /*description*/'虽然结果还算不错，\n但如果就这样感到满足，那我\n可就头疼了。作为惠理子小队的一员，\n你们要朝着更高的目标努力。', /*voice_id*/106, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/6, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/107, /*where_type*/24, /*character_id*/129901, /*face_type*/3, /*character_name*/'惠理子', /*description*/'在我的指导下，居然得到这样的结果……\n看来是时候更认真地考虑一下了。\n得好好想想，怎么样的教育才能让你们\n不再懈怠训练……嘻嘻。', /*voice_id*/107, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/10.6, /*change_face_type*/8, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/108, /*where_type*/24, /*character_id*/129901, /*face_type*/6, /*character_name*/'惠理子', /*description*/'是作为勉强完成训练的奖励，\n还是未能充分发挥全部实力的惩罚……\n你们该得到哪一种，\n这是我经过一番思考后的结果。', /*voice_id*/108, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/7.54, /*change_face_type*/4, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/109, /*where_type*/24, /*character_id*/129901, /*face_type*/2, /*character_name*/'惠理子', /*description*/'这场战斗的表现很不错。\n这都要归功于你们的努力，\n最重要的是，身为优秀教官的\n我的教诲，对吧？　嘻嘻嘻……', /*voice_id*/109, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/11.5, /*change_face_type*/7, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/110, /*where_type*/24, /*character_id*/129901, /*face_type*/2, /*character_name*/'惠理子', /*description*/'既然能走到这么远，算是合格了。\n不过，如果你们想追求\n更高的目标……我就陪你们\n继续训练吧。', /*voice_id*/110, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/8.83, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/111, /*where_type*/24, /*character_id*/129901, /*face_type*/1, /*character_name*/'惠理子', /*description*/'不成熟又靠不住的你们\n竟然有了翻天覆地的成长。\n原来如此……这就是所谓的\n作为教官的成就感吧。', /*voice_id*/111, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/6.68, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/112, /*where_type*/24, /*character_id*/129901, /*face_type*/6, /*character_name*/'惠理子', /*description*/'没想到你们居然能发挥出\n超乎我预期的力量……真让我吃惊。\n你已经不再是垃圾臭虫了，\n作为一名优秀的骑士昂首挺胸吧。', /*voice_id*/112, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/8.8, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/113, /*where_type*/24, /*character_id*/129901, /*face_type*/2, /*character_name*/'惠理子', /*description*/'嘻嘻，干得漂亮。\n我一直相信大家能够成功。\n毕竟，你们接受了我的指导，\n是惠理子小队的优秀新兵。', /*voice_id*/113, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/8.9, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/114, /*where_type*/24, /*character_id*/129901, /*face_type*/2, /*character_name*/'惠理子', /*description*/'多么优秀的成绩！\n今天将会作为“心怀着那位大人，\n惠理子超越极限的纪念日”\n而永载史册吧！', /*voice_id*/114, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/3.7, /*change_face_type*/5, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/200, /*where_type*/24, /*character_id*/129801, /*face_type*/1, /*character_name*/'真琴', /*description*/'好，今天的训练很不错。\n你们表现得很好，\n我觉得也有了成长。\n继续保持这种状态加油吧。', /*voice_id*/200, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/7.6, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/201, /*where_type*/24, /*character_id*/129801, /*face_type*/2, /*character_name*/'真琴', /*description*/'首先，祝贺你们到达终点！\n不过，努力是需要坚持的。\n如果你们还有干劲，\n不管多少次我都会陪你们的。', /*voice_id*/201, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/2.25, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/202, /*where_type*/24, /*character_id*/129801, /*face_type*/2, /*character_name*/'真琴', /*description*/'行军训练到此结束！\n你应该没这么认为吧？\n只有把学到的东西牢牢记住，\n脚踏实地反复练习，才能真正称得上是训练。', /*voice_id*/202, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/3.28, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/203, /*where_type*/24, /*character_id*/129801, /*face_type*/4, /*character_name*/'真琴', /*description*/'是不是让大家勉强自己了……\n不过，不能在这里放弃哦。\n下次一定能成功。只要坚信这一点，\n继续锻炼，一定就能开拓道路！', /*voice_id*/203, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/2.98, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/204, /*where_type*/24, /*character_id*/129801, /*face_type*/4, /*character_name*/'真琴', /*description*/'这个结果真是让人不甘心……\n不过，也有不少地方需要反思，\n一个一个地克服吧。\n让我们齐心协力，一起去实现，好吗！', /*voice_id*/204, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/3.0, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/205, /*where_type*/24, /*character_id*/129801, /*face_type*/1, /*character_name*/'真琴', /*description*/'你们还是不成熟的训练兵，\n失败了也没必要太过懊悔。\n不过，实战可不会这么轻松。\n下次要重新调整状态，好好努力！', /*voice_id*/205, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/10.3, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/206, /*where_type*/24, /*character_id*/129801, /*face_type*/6, /*character_name*/'真琴', /*description*/'这就是你们的全力以赴？\n不对不对，没这个可能吧。\n你们一定能变得更强！\n这可是我说的，绝对没错！', /*voice_id*/206, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/2.93, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/207, /*where_type*/24, /*character_id*/129801, /*face_type*/3, /*character_name*/'真琴', /*description*/'考虑到你们的实力，\n这个成绩不能算是全力以赴。\n既然如此，下次该做的也很明确了。\n调整心态，重新开始训练吧！', /*voice_id*/207, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/9.3, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/208, /*where_type*/24, /*character_id*/129801, /*face_type*/4, /*character_name*/'真琴', /*description*/'还有很多问题需要去解决啊～\n多余的动作、判断迟缓……\n只要认真改正这些问题，\n成绩一定也能更上一层楼。', /*voice_id*/208, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/6.9, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/209, /*where_type*/24, /*character_id*/129801, /*face_type*/2, /*character_name*/'真琴', /*description*/'能做到这一步，算是合格了！\n考虑到你们刚开始时那么不靠谱，\n不如说已经成长了很多吧？\n我认为这个结果很值得骄傲哦！', /*voice_id*/209, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/210, /*where_type*/24, /*character_id*/129801, /*face_type*/1, /*character_name*/'真琴', /*description*/'虽然训练很艰苦，\n但大家都没掉队啊。\n经过踏实反复的基础训练，终于开始\n看到成效了，这就是你们努力的证明。', /*voice_id*/210, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/5.95, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/211, /*where_type*/24, /*character_id*/129801, /*face_type*/2, /*character_name*/'真琴', /*description*/'这次训练你们也很努力！\n好好休息，为下次训练做准备吧！\n怎么说，看到自己的学员不断成长，\n真的是件让人开心的事啊……', /*voice_id*/211, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/6.73, /*change_face_type*/1, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/212, /*where_type*/24, /*character_id*/129801, /*face_type*/2, /*character_name*/'真琴', /*description*/'你们真厉害啊！\n这样一来，已经不能把你们\n称为小白新兵了。你们一定\n也能在骑士团里大显身手的！', /*voice_id*/212, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/0.0, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/213, /*where_type*/24, /*character_id*/129801, /*face_type*/1, /*character_name*/'真琴', /*description*/'和敌人战斗的方式、对战况的正确判断，\n最重要的毅力……每一项都非常出色！\n要是稍微掉以轻心，说不定连身为教官的我\n都要被你们赶超了……嘿嘿。', /*voice_id*/213, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/6.65, /*change_face_type*/2, /*event_id*/10142);
INSERT INTO `nbb_navi_comment` VALUES (/*comment_id*/214, /*where_type*/24, /*character_id*/129801, /*face_type*/6, /*character_name*/'真琴', /*description*/'我的指导很棒？\n没有没有，你们能变得这么强，\n归根结底还是因为你们自身的努力。\n再说一遍……祝贺你们！', /*voice_id*/214, /*start_time*/'2025/10/30 11:00:00', /*end_time*/'2099/12/17 14:59:59', /*pos_x*/0.0, /*pos_y*/0.0, /*change_face_time*/3.05, /*change_face_type*/1, /*event_id*/10142);
